// EDIT THIS NODE. One item per host comes out, each carrying the shared settings.
const settings = {
  capsule_base: 'https://api.capsulecrm.com/api/v2',
  pipeline_name: 'Enquiries',
  booked_milestone_name: 'Meeting Booked',
  move_from_milestones: ['New', 'Contacted'],   // only move forward from these
  timezone: 'Pacific/Auckland',
  internal_domains: ['example.co.nz'],           // attendees here are staff, not guests
  summary_match: [],                             // e.g. ['Discovery', 'Strategy'] to ignore every other meeting
  meeting_types: { discovery: { match: 'Discovery' }, strategy: { match: 'Strategy' } },
  tag_prefix: 'booking',
  first_run_lookback_hours: 24,
  overlap_minutes: 10,
  conversion_webhook: '',                        // optional: your own endpoint for server-side conversions
  hosts: [
    { name: 'Host One', email: 'one@example.co.nz', calendar_id: 'one@example.co.nz' },
    // { name: 'Host Two', email: 'two@example.co.nz', calendar_id: 'two@example.co.nz' },
  ],
};
const sd = $getWorkflowStaticData('global');
const now = new Date();
const since = sd.last_run
  ? new Date(new Date(sd.last_run).getTime() - settings.overlap_minutes * 60000)
  : new Date(now.getTime() - settings.first_run_lookback_hours * 3600000);
return settings.hosts.map(h => ({ json: { ...h, settings, updated_min: since.toISOString(), run_started: now.toISOString() } }));

// Pairs each Google response with its host by position, keeps events that have an
// outside guest, and skips anything already seen at the same `updated` stamp.
const hosts = $('Settings').all().map(i => i.json);
const responses = $input.all();
const sd = $getWorkflowStaticData('global');
sd.processed = sd.processed || {};
const out = [];
let anyError = false;
responses.forEach((item, idx) => {
  const host = hosts[idx];
  if (!host) return;
  if (item.json.error) { anyError = true; return; }
  const st = host.settings;
  const internalDomains = (st.internal_domains || []).map(d => String(d).toLowerCase());
  const isInternal = addr => {
    const a = String(addr || '').toLowerCase();
    if (!a || a === host.email.toLowerCase()) return true;
    return internalDomains.includes(a.split('@')[1] || '');
  };
  for (const ev of (item.json.items || [])) {
    const summary = ev.summary || '';
    if (st.summary_match && st.summary_match.length
        && !st.summary_match.some(m => summary.toLowerCase().includes(String(m).toLowerCase()))) continue;
    const guests = (ev.attendees || []).filter(a => a.email && !a.resource && !isInternal(a.email));
    if (!guests.length) continue;
    if (sd.processed[ev.id] === ev.updated) continue;
    sd.processed[ev.id] = ev.updated;
    const g = guests[0];
    out.push({ json: {
      action: ev.status === 'cancelled' ? 'cancelled' : 'booked',
      event_id: ev.id,
      updated: ev.updated,
      summary,
      start: (ev.start && (ev.start.dateTime || ev.start.date)) || '',
      end: (ev.end && (ev.end.dateTime || ev.end.date)) || '',
      link: ev.htmlLink || '',
      meet: ev.hangoutLink || '',
      description: String(ev.description || '').slice(0, 1500),
      guest_email: g.email.toLowerCase(),
      guest_name: g.displayName || '',
      guest_response: g.responseStatus || '',
      host: { name: host.name, email: host.email },
      settings: st,
    }});
  }
});
const cutoff = Date.now() - 60 * 86400000;
for (const [id, upd] of Object.entries(sd.processed)) {
  if (new Date(upd).getTime() < cutoff) delete sd.processed[id];
}
if (!anyError && hosts[0]) sd.last_run = hosts[0].run_started;
return out;

// Exact email match or nothing. A guest who booked from a direct link still gets a record.
const ev = $('Find new bookings and cancellations').item.json;
const res = $input.item.json || {};
const parties = Array.isArray(res.parties) ? res.parties : [];
const match = parties.find(p => (p.emailAddresses || []).some(e => (e.address || '').toLowerCase() === ev.guest_email));
const parts = (ev.guest_name || ev.guest_email.split('@')[0]).trim().split(/\s+/);
const create_body = { party: {
  type: 'person',
  firstName: parts[0] || ev.guest_email,
  lastName: parts.slice(1).join(' ') || undefined,
  emailAddresses: [{ type: 'Work', address: ev.guest_email }],
  tags: [{ name: 'form:booking' }, { name: 'src:calendar-direct' }],
}};
return { json: { ...ev, party_id: match ? match.id : null, create_body } };

const base = $('Match person').item.json;
const inp = $input.item.json || {};
const party_id = base.party_id || (inp.party && inp.party.id) || null;
if (!party_id) throw new Error('No Capsule person id. Response was: ' + JSON.stringify(inp).slice(0, 300));
return { json: { ...base, party_id } };

// Which opportunity, which milestone, which tags, and the note text.
const ev = $('Resolve person').item.json;
const st = ev.settings;
const opps = ($('Capsule: list opportunities').item.json || {}).opportunities || [];
const milestones = ($input.item.json || {}).milestones || [];
const inPipeline = m => !m.pipeline || !st.pipeline_name
  || (m.pipeline.name || '').toLowerCase() === st.pipeline_name.toLowerCase();
const pipelineMs = milestones.filter(inPipeline);
const booked = pipelineMs.find(m => (m.name || '').toLowerCase() === st.booked_milestone_name.toLowerCase());
const ids = new Set(pipelineMs.map(m => m.id));
const open = opps
  .filter(o => !o.closedOn && (!o.milestone || ids.size === 0 || ids.has(o.milestone.id)))
  .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')))[0];
const typeEntry = Object.entries(st.meeting_types || {})
  .find(([k, v]) => ev.summary.toLowerCase().includes(String(v.match || k).toLowerCase()));
const typeKey = typeEntry ? typeEntry[0] : 'meeting';
const tags = [ev.action === 'cancelled' ? `${st.tag_prefix}:cancelled` : `${st.tag_prefix}:${typeKey}`];
const when = ev.start
  ? new Date(ev.start).toLocaleString('en-NZ', { timeZone: st.timezone || 'UTC', dateStyle: 'full', timeStyle: 'short' })
  : 'unknown time';
const lines = ev.action === 'cancelled'
  ? [`Meeting cancelled: ${ev.summary}`, `Was: ${when}`, `Host: ${ev.host.name}`, `Event id: ${ev.event_id}`]
  : [`Meeting booked: ${ev.summary}`, `When: ${when}`, `Host: ${ev.host.name}`,
     ev.meet ? `Meet: ${ev.meet}` : null, ev.link ? `Calendar: ${ev.link}` : null,
     ev.description ? `Booking form answers:\n${ev.description}` : null, `Event id: ${ev.event_id}`];
const note = lines.filter(Boolean).join('\n');
const create_opportunity = ev.action === 'booked' && !open;
if (create_opportunity && !booked) throw new Error(`No milestone "${st.booked_milestone_name}" in pipeline "${st.pipeline_name}". See capsule/SCHEMA.md.`);
const fromOk = !open || !open.milestone
  || (st.move_from_milestones || []).map(x => String(x).toLowerCase()).includes(String(open.milestone.name || '').toLowerCase());
const canMove = !!(open && booked && ev.action === 'booked' && fromOk);
const update_body = open
  ? { opportunity: { ...(canMove ? { milestone: { id: booked.id } } : {}), tags: tags.map(name => ({ name })) } }
  : null;
const create_body = create_opportunity
  ? { opportunity: { party: { id: ev.party_id }, name: `${ev.guest_name || ev.guest_email} - ${ev.summary}`.slice(0, 100),
      milestone: { id: booked.id }, tags: tags.map(name => ({ name })) } }
  : null;
return { json: { ...ev, opportunity_id: open ? open.id : null, create_opportunity,
  opportunity_create_body: create_body, opportunity_update_body: update_body, note, tags, meeting_type: typeKey } };

// A cancellation with no open opportunity is fine: the note goes on the person instead.
const base = $('Decide update').item.json;
const inp = $input.item.json || {};
const opportunity_id = base.opportunity_id || (inp.opportunity && inp.opportunity.id) || null;
return { json: { ...base, opportunity_id } };
